-- ============================================================================
-- 4. CAPA 3: DOMINIO DE PRÁCTICAS PROFESIONALES
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Tabla: internships
-- Trámite maestro de Prácticas Profesionales (200 a 480 horas, 2 créditos).
-- Incorpora control de convenios, actas a escolares, checklist OK y oficios.
-- ----------------------------------------------------------------------------
CREATE TABLE internships (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    student_id bigint NOT NULL,
    period_id bigint NOT NULL,
    company_id bigint NULL,
    supervisor_id bigint NULL,
    agreement_id bigint NULL,
    semester_enrolled integer NOT NULL,
    start_date date NULL,
    end_date date NULL,
    schedule_description varchar(150) NULL,
    required_hours integer NOT NULL DEFAULT 200,
    completed_hours integer NOT NULL DEFAULT 0,
    status varchar(32) NOT NULL DEFAULT 'requested',
    credits_awarded integer NOT NULL DEFAULT 2,
    presentation_letter_folio varchar(64) NULL,
    presentation_letter_date date NULL,
    acceptance_letter_date date NULL,
    termination_letter_date date NULL,
    original_termination_letter_received boolean NOT NULL DEFAULT false,
    release_certificate_folio varchar(64) NULL,
    release_date date NULL,
    released_at timestamp with time zone NULL,
    is_expedient_complete boolean NOT NULL DEFAULT false,
    school_services_act_sent boolean NOT NULL DEFAULT false,
    school_services_act_sent_at timestamp with time zone NULL,
    school_services_act_folio varchar(64) NULL,
    observations text NULL,
    cancellation_reason text NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT fk_internships__students FOREIGN KEY (student_id)
        REFERENCES students (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_internships__academic_periods FOREIGN KEY (period_id)
        REFERENCES academic_periods (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_internships__companies FOREIGN KEY (company_id)
        REFERENCES companies (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_internships__company_supervisors FOREIGN KEY (supervisor_id)
        REFERENCES company_supervisors (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_internships__agreements FOREIGN KEY (agreement_id)
        REFERENCES agreements (id)
        ON UPDATE CASCADE
        ON DELETE SET NULL,
    CONSTRAINT ck_internships__semester CHECK (semester_enrolled BETWEEN 1 AND 15),
    CONSTRAINT ck_internships__dates CHECK (start_date IS NULL OR end_date IS NULL OR end_date >= start_date),
    CONSTRAINT ck_internships__required_hours CHECK (required_hours BETWEEN 200 AND 480),
    CONSTRAINT ck_internships__completed_hours CHECK (completed_hours >= 0),
    CONSTRAINT ck_internships__status CHECK (
        status IN (
            'requested', 'approved', 'accepted', 'active',
            'completed_pending_review', 'released', 'cancelled', 'non_compliant'
        )
    ),
    CONSTRAINT ck_internships__credits CHECK (credits_awarded = 2)
);

CREATE INDEX idx_internships__student_id ON internships (student_id);
CREATE INDEX idx_internships__period_id ON internships (period_id);
CREATE INDEX idx_internships__company_id ON internships (company_id);
CREATE INDEX idx_internships__supervisor_id ON internships (supervisor_id);
CREATE INDEX idx_internships__agreement_id ON internships (agreement_id);
CREATE INDEX idx_internships__status ON internships (status);
CREATE INDEX idx_internships__school_services_act ON internships (school_services_act_sent);
CREATE INDEX idx_internships__deleted_at ON internships (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: internship_evaluations
-- Formato oficial Anexo XVII (Evaluación al desempeño: PRODUCTIVIDAD LABORAL).
-- 7 criterios numéricos (0 a 4), promedio y nivel de desempeño.
-- ----------------------------------------------------------------------------
CREATE TABLE internship_evaluations (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    internship_id bigint NOT NULL,
    activity_name varchar(100) NOT NULL DEFAULT 'PRODUCTIVIDAD LABORAL',
    evaluation_start_date date NOT NULL,
    evaluation_end_date date NOT NULL,
    criterion_1 integer NOT NULL,
    criterion_2 integer NOT NULL,
    criterion_3 integer NOT NULL,
    criterion_4 integer NOT NULL,
    criterion_5 integer NOT NULL,
    criterion_6 integer NOT NULL,
    criterion_7 integer NOT NULL,
    numerical_average numeric(3,2) NOT NULL,
    performance_level varchar(32) NOT NULL,
    is_competency_achieved boolean NOT NULL,
    evaluator_supervisor_id bigint NULL,
    evaluator_signature_date date NOT NULL,
    observations text NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT fk_internship_evaluations__internships FOREIGN KEY (internship_id)
        REFERENCES internships (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_internship_evaluations__supervisor FOREIGN KEY (evaluator_supervisor_id)
        REFERENCES company_supervisors (id)
        ON UPDATE CASCADE
        ON DELETE SET NULL,
    CONSTRAINT ck_internship_eval__dates CHECK (evaluation_end_date >= evaluation_start_date),
    CONSTRAINT ck_internship_eval__c1 CHECK (criterion_1 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c2 CHECK (criterion_2 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c3 CHECK (criterion_3 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c4 CHECK (criterion_4 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c5 CHECK (criterion_5 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c6 CHECK (criterion_6 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c7 CHECK (criterion_7 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__avg CHECK (numerical_average BETWEEN 0.00 AND 4.00),
    CONSTRAINT ck_internship_eval__level CHECK (
        performance_level IN ('excellent', 'notable', 'good', 'sufficient', 'insufficient')
    )
);

CREATE UNIQUE INDEX uq_internship_evaluations__internship_id ON internship_evaluations (internship_id) WHERE deleted_at IS NULL;
CREATE INDEX idx_internship_evaluations__supervisor_id ON internship_evaluations (evaluator_supervisor_id);
CREATE INDEX idx_internship_evaluations__deleted_at ON internship_evaluations (deleted_at);

-- ============================================================================
-- 5. CAPA 4: TRAZABILIDAD, AUDITORÍA Y CALIDAD ISO 9001
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Tabla: tramite_status_logs
-- Bitácora inmutable de transiciones de estado para auditorías y tiempos de ciclo.
-- ----------------------------------------------------------------------------
CREATE TABLE tramite_status_logs (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tramite_type varchar(32) NOT NULL,
    tramite_id bigint NOT NULL,
    previous_status varchar(32) NULL,
    new_status varchar(32) NOT NULL,
    reason text NULL,
    changed_by bigint NOT NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT fk_tramite_status_logs__users FOREIGN KEY (changed_by)
        REFERENCES users (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT ck_tramite_status_logs__type CHECK (
        tramite_type IN ('social_service', 'internship', 'residency')
    )
);

CREATE INDEX idx_tramite_status_logs__tramite ON tramite_status_logs (tramite_type, tramite_id);
CREATE INDEX idx_tramite_status_logs__changed_by ON tramite_status_logs (changed_by);
CREATE INDEX idx_tramite_status_logs__created_at ON tramite_status_logs (created_at);
CREATE INDEX idx_tramite_status_logs__deleted_at ON tramite_status_logs (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: non_conformances
-- Registro formal de Producto No Conforme (PNC) para auditorías ISO 9001:2015.
-- ----------------------------------------------------------------------------
CREATE TABLE non_conformances (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tramite_type varchar(32) NOT NULL,
    tramite_id bigint NOT NULL,
    student_id bigint NOT NULL,
    period_id bigint NOT NULL,
    incident_code varchar(64) NOT NULL,
    category varchar(32) NOT NULL,
    description text NOT NULL,
    status varchar(32) NOT NULL DEFAULT 'open',
    action_plan text NULL,
    resolved_at timestamp with time zone NULL,
    resolved_by bigint NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT fk_non_conformances__students FOREIGN KEY (student_id)
        REFERENCES students (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_non_conformances__academic_periods FOREIGN KEY (period_id)
        REFERENCES academic_periods (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_non_conformances__resolver FOREIGN KEY (resolved_by)
        REFERENCES users (id)
        ON UPDATE CASCADE
        ON DELETE SET NULL,
    CONSTRAINT ck_non_conformances__tramite CHECK (
        tramite_type IN ('social_service', 'internship', 'residency')
    ),
    CONSTRAINT ck_non_conformances__category CHECK (
        category IN ('desertion', 'delayed_reports', 'company_dismissal', 'insufficient_grade', 'invalid_documents', 'other')
    ),
    CONSTRAINT ck_non_conformances__status CHECK (
        status IN ('open', 'under_review', 'resolved', 'cancelled')
    )
);

CREATE UNIQUE INDEX uq_non_conformances__incident_code ON non_conformances (incident_code) WHERE deleted_at IS NULL;
CREATE INDEX idx_non_conformances__tramite ON non_conformances (tramite_type, tramite_id);
CREATE INDEX idx_non_conformances__student_id ON non_conformances (student_id);
CREATE INDEX idx_non_conformances__period_id ON non_conformances (period_id);
CREATE INDEX idx_non_conformances__status ON non_conformances (status);
CREATE INDEX idx_non_conformances__deleted_at ON non_conformances (deleted_at);

COMMIT;


